export default {"id":"note-level-17","number":17,"title":"C Troubleshooting","skillBand":"Textbook","duration":"From the course textbook","summary":"c.1","modules":[{"id":"note-m-1-101-3","code":"1","title":"c.1","blurb":"c.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-1","title":"C.1 — Bluetooth lag: use wired headphones","blocks":[{"type":"step","title":"C.1 — Bluetooth lag: use wired headphones","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat Bluetooth delay as documented latency, not a broken Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Bluetooth Headphones and Latency in Note: wireless headphones can delay instrument play and playback. Codecs add <strong>34–200 ms</strong>; wired averages <strong>5–10 ms</strong>. Ableton recommends a wired adapter. Newer Bluetooth can help but is limited by the device’s radio. If latency seems abnormal, unpair in iOS Settings → Bluetooth and pair again."},{"type":"prose","html":"FAQ: “We recommend connecting wired headphones to play the instruments in Note.”"},{"type":"prose","html":"This is expected physics, not a Cloud or Capture bug."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["If you hear lag between pad and sound, note whether you are on Bluetooth.","Plug in wired headphones (or a dongle). Play the same pad.","Optional: unpair/re-pair Bluetooth if you must stay wireless.","Recite: 34–200 ms wireless vs 5–10 ms wired."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What latency range does the KB give for Bluetooth? <strong>Answer:</strong> 34–200 milliseconds.","First fix? <strong>Answer:</strong> Wired headphones.","Is this a Note Cloud problem? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Bluetooth Headphones and Latency in Note","Note FAQ (Bluetooth / AirPods)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add “wired for Capture” to the travel kit (11.3.11)."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-1</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-2-102-3","code":"2","title":"c.2","blurb":"c.2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-2","title":"C.2 — Cloud missing in Live: same account, Show Cloud, Live version","blocks":[{"type":"step","title":"C.2 — Cloud missing in Live: same account, Show Cloud, Live version","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Walk the official four-step Cloud-not-appearing card before you rebuild a Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"<em>Note Sets in Ableton Cloud not Appearing in Live</em> (Live 11.2.5+):"},{"type":"list","items":["Confirm internet (Wi-Fi or Note cellular allowed). Uploads can take seconds to minutes.","Enable Cloud in <strong>both</strong> Note and Live. <strong>Same Ableton email</strong> as the Live license.","Re-enable: toggle Cloud off/on in Note, sign out/in in the browser if the wrong account is cached; in Live, sign out of the Cloud label and Sign In again.","Check the Ableton Status page for a Cloud outage."],"ordered":true},{"type":"prose","html":"FAQ: sign in with the email on the Live license. Show Cloud lives in Live Settings → Library."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Tick: internet, Cloud on in Note, Cloud visible in Live Places, same email, Live ≥ 11.2.5.","If missing, do the re-enable dance in the KB (Note toggle, Live Sign Out/In).","Wait for sync. Large Sets take minutes (Move Cloud KB; Cloud upload times).","Recite the four steps."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What is the most common account mistake? <strong>Answer:</strong> Different emails on Note vs Live.","Minimum Live version? <strong>Answer:</strong> 11.2.5.","Does a status outage mean your Set is gone? <strong>Answer:</strong> No. Wait; local copy still exists (FAQ)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Sets in Ableton Cloud not Appearing in Live","Note FAQ (same email; 8 Sets)","Setting Up Ableton Cloud"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write the email you use for Cloud on the compatibility card. That string is the whole login."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-2</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-3-103-3","code":"3","title":"c.3","blurb":"c.3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-3","title":"C.3 — Orange microphone icon is expected","blocks":[{"type":"step","title":"C.3 — Orange microphone icon is expected","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Leave the iOS orange microphone indicator alone; Note accesses the mic by default."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note FAQ, Reporting Problems: “When I'm using Note, an orange microphone icon appears in iOS. Is this expected? Note accesses the microphone of your device by default. This is indicated by the orange microphone icon displayed in iOS, which is expected.”"},{"type":"prose","html":"Manual §1.1: Note requests microphone access on first launch (or later via Settings → Privacy → Microphone) so you can record samples."},{"type":"prose","html":"This is not a hidden recorder stealing the Set. If you deny the mic, sampling/recording prompts you to enable it (Working with Samples)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open Note. Notice the orange mic (or iOS privacy pill).","Confirm iOS Settings → Privacy → Microphone → Note is on if you need to sample.","Do not file a bug for the icon alone (FAQ: expected).","Recite: orange mic = Note’s default mic access."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Is the orange icon a crash? <strong>Answer:</strong> No. FAQ: expected.","Why does Note want the mic? <strong>Answer:</strong> To record samples (Manual §1.1).","Where do you re-grant access? <strong>Answer:</strong> iOS Settings → Privacy → Microphone."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (orange microphone icon)","Ableton Note Manual §1.1","Working with Samples in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If you teach, say this sentence before students panic: “The orange dot means the sampler can hear you.”"},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-3</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-4-104-3","code":"4","title":"c.4","blurb":"c.4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-4","title":"C.4 — Sample timing/key: sampler couple vs 2.x audio warp","blocks":[{"type":"step","title":"C.4 — Sample timing/key: sampler couple vs 2.x audio warp","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Diagnose “my loop is the wrong speed in this key” by path: Sampler vs 2.0.1 audio track."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: on Sampler or Drum Rack, <strong>Transpose</strong> re-pitches <strong>and</strong> changes speed. Warp is not available on that path."},{"type":"prose","html":"RN 2.0.1: audio-track loops <strong>are</strong> warped — tempo and pitch independent."},{"type":"prose","html":"If a student transposed a vocal on Melodic Sampler to C and it got shorter, that is the FAQ, not a bug. Fix: use an <strong>Audio</strong> track on 2.0.1+, or pick pads around C3 instead of huge Transpose, or accept the speed change."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Ask: is the file on Drum/Melodic Sampler or on an Audio track?","Sampler: read 7.5.8. Stop treating it like Live warp.","2.0.1 Audio: use clip tempo / transpose dials (9.5.8–9.5.9).","Check Help version before you promise warp.","Recite both rules."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Sampler Transpose changes what? <strong>Answer:</strong> Pitch and speed (FAQ).","Where is independent tempo/pitch? <strong>Answer:</strong> Note 2.0.1 audio tracks (RN).","Is “Warp is not available” always true in 2.x? <strong>Answer:</strong> True for Sampler. False for audio tracks. Version-gate."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (Making Music with Note)","Note Release Notes 2.0.1","Lessons 7.5.8, 9.5.8"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write the two-path diagram on the troubleshooting card."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-4</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-5-105-3","code":"5","title":"c.5","blurb":"c.5","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-5","title":"C.5 — Upload stuck: network, 100 MB, characters, status","blocks":[{"type":"step","title":"C.5 — Upload stuck: network, 100 MB, characters, status","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Unstick a Cloud upload using only documented causes."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Documented blockers:"},{"type":"list","items":["<strong>No network:</strong> Manual §2.1 — uploads wait until Wi-Fi or cellular is available. Cloud-not-appearing KB: confirm Mobile Data allowed or Wi-Fi on.","<strong>100 MB samples:</strong> RN 1.0.6 — cannot import/select over 100 MB; Cloud warns. Crop (1.7.3).","<strong>Illegal characters:</strong> RN 1.0.12 added <strong>colon</strong> to the forbidden list. Rename the Set.","<strong>Status outage:</strong> Cloud-not-appearing step 4 — Ableton Status page.","<strong>Move path:</strong> Sets &gt; 50 MB may fail (Move Cloud KB) if this Set is also going to Move.","<strong>Demo Sets:</strong> RN 1.0.12 fixed demo-upload bugs — do not upload demos."],"ordered":false},{"type":"prose","html":"Uploads can take minutes. “Stuck” is often “slow.”"}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Confirm Wi-Fi or allowed cellular.","Check sample sizes and Set name (no <code>:</code>).","Check Ableton Status.","Toggle Cloud off/on (C.2) if the account is wrong.","Recite: network, 100 MB, colon, status."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What character did 1.0.12 forbid? <strong>Answer:</strong> Colon (<code>:</code>).","What sample size cannot be selected? <strong>Answer:</strong> Larger than 100 MB.","Are demo Sets good Cloud tests? <strong>Answer:</strong> No."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.1","Note Release Notes 1.0.6, 1.0.12, 1.7.3","Note Sets in Cloud not Appearing","Using Move with Ableton Cloud (50 MB)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Rename any Set with a colon. Re-upload."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-5</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-6-106","code":"6","title":"c.6","blurb":"c.6","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-6","title":"C.6 — Crash: auto report, update, write the version","blocks":[{"type":"step","title":"C.6 — Crash: auto report, update, write the version","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"After a crash, do not file a empty ticket. Note already reported it; you add steps and a version."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"FAQ: if Note crashes, a crash report is sent automatically. “There is no need to contact Ableton Support” for that alone."},{"type":"prose","html":"If you find a <strong>reproducible</strong> bug: list exact steps and submit via the contact form while logged into an Ableton account. Help → Feedback for suggestions (Manual §2.5). Version number lives on the Help page — include it."},{"type":"prose","html":"Auto-save every 10–15 seconds (FAQ) limits loss. RN 1.1.2: tap the version number <strong>five times</strong> to gather diagnostics. TestFlight beta is on the Help screen (RN 1.1.2)."},{"type":"prose","html":"Screen recording (B.4) is extra evidence for Support."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Relaunch Note. Open the Set. Check you only lost ~15 seconds (FAQ).","Write Help version. Update from the App Store if you are behind.","If it happens again, write numbered steps. Optional: five-tap diagnostics (1.1.2).","Submit via the account contact form only if you can reproduce.","Recite: auto report; version; steps."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Do you email Support for every crash? <strong>Answer:</strong> FAQ says auto-report is enough unless you have a reproducible case.","How often does Note auto-save? <strong>Answer:</strong> About every 10–15 seconds.","Where is the version? <strong>Answer:</strong> Settings → Help."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note FAQ (crash; auto-save; contact form)","Ableton Note Manual §2.5","Note Release Notes 1.1.2 (five-tap diagnostics; TestFlight)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Write your current version on the troubleshooting card now, before the next crash."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-6</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-7-107","code":"7","title":"c.7","blurb":"c.7","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-7","title":"C.7 — Live “new file format” warning (Note 1.1.1)","blocks":[{"type":"step","title":"C.7 — Live “new file format” warning (Note 1.1.1)","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"If Live says the Note document is a newer format, treat it as the <strong>1.1.1 metadata bug</strong>, not a Live upgrade."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note Release Notes <strong>1.1.1</strong>: Live incorrectly showed “This document is in a new file format version. The document will sound different from when it was last saved.” Cause: <strong>incorrect metadata written by Note</strong>. “There is no need to update Live.” Re-save the affected Sets from <strong>updated Note</strong> (1.1.1+) to stop the message."},{"type":"prose","html":"This is the opposite of a real format bump. Updating Live will not fix old Note metadata."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Read the exact Live dialog. If it matches 1.1.1’s wording, do <strong>not</strong> rush a Live update for this reason alone.","Update Note past 1.1.1 (Help).","Open the Set in Note and save (auto-save or a small edit).","Re-open in Live. Confirm the warning is gone.","Recite: Note metadata; re-save in new Note; no Live update required."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What caused the warning? <strong>Answer:</strong> Incorrect metadata from Note (RN 1.1.1).","Should you update Live to fix it? <strong>Answer:</strong> No. Re-save from updated Note.","Where do you confirm Note’s version? <strong>Answer:</strong> Settings → Help."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.1.1","Note Compatibility (real minimum is still Live 11.2.5 for opening Sets)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If any course Set still warns, re-save it today and tick this row on the card."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-7</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-8-108","code":"8","title":"c.8","blurb":"c.8","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-8","title":"C.8 — Sets overwrite each other: unique names, no rapid open/close","blocks":[{"type":"step","title":"C.8 — Sets overwrite each other: unique names, no rapid open/close","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Avoid documented library overwrite bugs: unique names, and do not slam Sets open and shut."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Note Release Notes:"},{"type":"list","items":["<strong>1.0.14:</strong> “Sets sometimes could get overwritten after leaving a Set and previewing another Set.”","<strong>1.5:</strong> “Set Library: Fixed cases where sets could overwrite each other when opened and closed in quick succession.”"],"ordered":false},{"type":"prose","html":"FAQ auto-save is not a version history. Unique Set names (Set Options → Rename) plus Share To archives (13.5.3) are the defense. Colon is illegal (RN 1.0.12)."},{"type":"prose","html":"If two Sets still look swapped, park both as <code>.ablbundle</code> before you delete anything (Troubleshooting Note Files)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Rename working Sets with unique titles (no <code>:</code>).","Do not preview-spam the library play buttons while a Set is still closing.","After a scare, Share To Files immediately.","Update Note if you are older than 1.5.","Recite: unique names; no rapid open/close; park first."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Which RNs mention overwrite? <strong>Answer:</strong> 1.0.14 and 1.5.","Is auto-save a history stack? <strong>Answer:</strong> No. It overwrites in place about every 10–15 seconds (FAQ).","First recovery move? <strong>Answer:</strong> Share To a <code>.ablbundle</code> before deleting."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.14, 1.5, 1.0.12","Note FAQ (auto-save)","Sharing Note Sets; Troubleshooting Note Files"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Audit the library for duplicate or generic names (“Set,” “Untitled”). Rename today."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-8</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-9-109","code":"9","title":"c.9","blurb":"c.9","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-c-9","title":"C.9 — No audio: disable iOS Sound Recognition","blocks":[{"type":"step","title":"C.9 — No audio: disable iOS Sound Recognition","blocks":[{"type":"prose","html":"<em>APPENDIX C · Official troubleshooting card</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"If Note is silent or recording fails, turn off iOS <strong>Sound Recognition</strong> before you rebuild the Set."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Troubleshooting Audio Output on Note: iOS Accessibility <strong>Sound Recognition</strong> (detects environmental sounds) has been reported to interfere with Note playback and recording."},{"type":"prose","html":"Official steps:"},{"type":"list","items":["iPhone <strong>Settings</strong>","<strong>Accessibility</strong>","Under Hearing, <strong>Sound Recognition</strong>","Turn the toggle <strong>off</strong>"],"ordered":true},{"type":"prose","html":"You can add Sound Recognition to Control Center for faster access (same KB)."},{"type":"prose","html":"Also check: Silent Mode / ring switch, Bluetooth routing (C.1), and that the track is not muted (Manual mixer <strong>M</strong>). Those are separate, sourced checks."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Play a Demo Set. If you hear nothing, continue.","Disable Sound Recognition (path above).","Recheck mute/solo and headphone path.","Recite: Sound Recognition can break Note audio; turn it off."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where is Sound Recognition? <strong>Answer:</strong> iOS Settings → Accessibility → Hearing → Sound Recognition.","Is this a Note preference? <strong>Answer:</strong> No. It is an iOS Accessibility feature.","What else should you check? <strong>Answer:</strong> Mute/solo, Bluetooth vs wired, system volume / Main."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Troubleshooting Audio Output on Note","Ableton Note Manual §4.4 Mixer","Bluetooth Headphones and Latency in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Add Sound Recognition to Control Center (KB) so you can kill it quickly in class."},{"type":"prose","html":"<em>Syllabus ID: <code>note-c-9</code></em>"}]}],"minutes":8}],"exercises":[]}]};
